F = {k: root / v for k, v in {"app": "src/App.tsx", "ws": "src/components/Building3DWorkspace.tsx", "roof": "src/components/RoofEditor148.tsx", "css": "src/styles.css", "icon": "src/components/StromIcon.tsx", "icon150": "src/components/StromIcon150.tsx", "sprite": "public/strom-icons-v7.svg"}.items()}
BASE = {"app": "120714da69fde4b953fff42e3631ace6655fb171b74512948a26094dcb9c53f7", "ws": "44b2793796aa7ea4fa38d44cb24a135ff5ce02bca11d54b85bc78d8800caca3b", "roof": "f887ba74eb69ad801e0bb1cb2eacbc3da614a8cae2c0f2bdf1ea3576208aef55", "css": "718ca9d9562b76e9291f84954a58eebe82598d52951b8ec4ba3535b350d26455", "icon": "9596fdd11b237d33b3cfd78ce3178e61e57aace1a3bc04add8a2661689f3ac6b", "icon150": "1f44559856dcc12ad7c4f912c954aa107f2be3e1fe2182db21917c3422c97b57", "sprite": "cec411fb87dc3327588883f8647e2a5adb0eb61c1fca46057deeacc58575a6e3"}
APP_EDITS = [('Import StromIcon150', "import StromIcon150 from './components/StromIcon150'\n", ''), ('Schliessen (2x)', '<StromIcon150 name="close" title="Schließen" />', '<StromIcon name="close" title="Schließen" />', 2), ('Wand klassisch: Rueckgaengig', '<StromIcon150 name="undo" title="Rückgängig" />', '<StromIcon name="undo" title="Rückgängig" />'), ('Wand klassisch: Drehen', 'onClick={() => setViewTool(\'rotate\')}><StromIcon150 name="rotate" title="Drehen" />', 'onClick={() => setViewTool(\'rotate\')}><StromIcon name="rotate-view" title="Ansicht drehen" />'), ('Wand klassisch: Zuruecksetzen', 'onClick={resetWallViewportRotation}><StromIcon150 name="rotate" title="Drehen" />', 'onClick={resetWallViewportRotation}><StromIcon name="reset-camera" title="Ansicht zurücksetzen" />'), ('Wand klassisch: Zoom -', '<StromIcon150 name="zoomOut" title="Verkleinern" />', '<StromIcon name="zoom-out" title="Herauszoomen" />'), ('Wand klassisch: 1:1', '<StromIcon150 name="zoomOne" title="Originalgröße" />', '<StromIcon name="one-to-one" title="100 Prozent Ansicht" />'), ('Wand klassisch: Zoom +', '<StromIcon150 name="zoomIn" title="Vergrößern" />', '<StromIcon name="zoom-in" title="Hineinzoomen" />'), ('Wand klassisch: Einpassen', '<StromIcon150 name="fullscreen" title="Vollbild" />', '<StromIcon name="fit" title="Alles einpassen" />'), ('Wand klassisch: Auswahl', '<StromIcon150 name="focus" title="Zentrieren" />', '<StromIcon name="target" title="Auf Auswahl zoomen" />'), ('Wand klassisch: Ebenenmenue', '<StromIcon150 name="menu" title="Menü" />', '<StromIcon name="chevron-down" title="Ebenenmenü" />'), ('Navigation Blueprint', '<StromIcon150 name="blueprint" title="Blueprint" />', '<StromIcon name="blueprint" title="Blueprint" />'), ('Navigation Wanddetail', '<StromIcon150 name="wall" title="Wanddetail" />', '<StromIcon name="wall-detail" title="Wanddetail" />'), ('Navigation Verteiler', '<StromIcon150 name="power" title="Elektrik" />', '<StromIcon name="lightning" title="Ve