ICON_CSS = '/* STROM169_ICONS: ein Iconsatz fuer die ganze Anwendung (Entwurf v7, Duoton wie Blender / 3ds Max). */\n.strom-icon { display:inline-block; flex:none; vertical-align:middle; overflow:visible; color:inherit; --si-accent:#2563eb; }\n.strom-icon * { fill:none; stroke:currentColor; stroke-width:1.75; stroke-linecap:round; stroke-linejoin:round; }\n.strom-icon .t { fill:currentColor; fill-opacity:.13; stroke:none; }\n.strom-icon .a { stroke:var(--si-accent); }\n.strom-icon .at { fill:var(--si-accent); fill-opacity:.2; stroke:none; }\n.strom-icon .af { fill:var(--si-accent); stroke:none; }\n.strom-icon .k { fill:currentColor; stroke:none; }\n.strom-icon .thin { stroke-width:1.2; }\n.strom-icon[data-tone="nav"], .strom-icon[data-tone="create"], .strom-icon[data-tone="edit"], .strom-icon[data-tone="object"] { --si-accent:#2563eb; }\n.strom-icon[data-tone="danger"] { --si-accent:#dc2626; }\n.strom-icon[data-tone="view"] { --si-accent:#0e7490; }\n.strom-icon[data-tone="layer"] { --si-accent:#7c3aed; }\n.strom-icon[data-tone="stair"] { --si-accent:#c2410c; }\n.strom-icon[data-tone="power"] { --si-accent:#d97706; }\n/* Auf farbigem (aktivem) Grund uebernimmt der Akzent die Schriftfarbe. */\nbutton.active .strom-icon, .btn.active .strom-icon, button[aria-pressed="true"] .strom-icon,\n.nav-list button.active .strom-icon { --si-accent:currentColor; }\n\n/* STROM169_ICONS: Treppen-Bibliothek zeigt die Icons 47–54 statt eigener CSS-Zeichnungen. */\n.stair-floating-window .stair-library-graphic.stair-library-icon169 { display:grid; place-items:center; color:#7c2d12; }\n.stair-floating-window .stair-library-graphic.stair-library-icon169::before,\n.stair-floating-window .stair-library-graphic.stair-library-icon169::after { content:none !important; display:none !important; }\n/* Werkzeugknoepfe mit Icon + Text (3D / Wanddetail): Icon und Beschriftung in einer Zeile. */\n.building3d-toolbar button, .wall-detail-legacy-wrapper > button { display:inline-flex; align-items:center; gap:6px; }\n.building3d-toolbar button .strom-icon, .wall-detail-legacy-wrapper > button .strom-icon { width:19px; height:19px; }\n.object-panel .collapse-toggle .strom-icon { width:18px; height:18px; }\n.layer-eye .strom-icon { width:18px; height:18px; }\n'
RESOURCES = {'StromIcon.tsx': 'import { iconAlias169, iconSet169 } from \'./iconSet169\'\n\ntype StromIconProps = {\n  name: string\n  title?: string\n  size?: number\n  className?: string\n}\n\nconst escape169 = (text: string) => text.replace(/[&<>"]/g, (c) => ({ \'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'"\': \'&quot;\' }[c] as string))\n\n/** STROM169_ICONS: einheitliche SVG-Icons ohne Nachladen (vorher Sprite-Datei + zweiter Iconsatz). */\nexport default function StromIcon({ name, title, size = 20, className = \'\' }: StromIconProps) {\n  const key = iconSet169[name] ? name : iconAlias169[name]\n  const entry = key ? iconSet169[key] : undefined\n  const body = entry ? entry[1] : \'\'\n  return (\n    <svg\n      className={`strom-icon strom-ui-icon ${className}`.trim()}\n      data-icon={key || name}\n      data-tone={entry ? entry[0] : \'nav\'}\n      width={size}\n      height={size}\n      viewBox="0 0 24 24"\n      role={title ? \'img\' : undefined}\n      aria-hidden={title ? undefined : true}\n      aria-label={title}\n      focusable="false"\n      dangerouslySetInnerHTML={{ __html: (title ? `<title>${escape169(title)}</title>` : \'\') + body }}\n    />\n  )\n}\n', 'StromIcon150.tsx': "import StromIcon from './StromIcon'\n\n/** STROM169_ICONS: frueherer zweiter Iconsatz. Leitet nur noch auf das einheitliche Set weiter. */\nexport default function StromIcon150({ name, title, size = 20, className }: { name: string; title?: string; size?: number; className?: string }) {\n  return <StromIcon name={name} title={title} size={size} className={className} />\n}\n", 'iconSet169.ts': '/** STROM169_ICONS: ein Iconsatz fuer die ganze Anwendung.\n * Entwurf v7 (strom_iconset_entwurf_v7.html) im 24er Raster, Linie 1,75, Duoton wie Blender / 3ds Max:\n * Tinte fuer die Form, Akzentfarbe fuer den wirksamen Teil. Farbe je Gruppe (data-tone, styles.css).\n * Klassen: t = Flaeche 13 %, a = Akzentlinie, at = Akzentflaeche 20 %, af = Akzent voll, k = Tinte voll, thin = 1,2er Linie.\n * Generiert von Update 169; Aenderungen bitte hier und im Iconblatt docs/STROM_ICONSET_169.html gemeinsam pflegen. */\nexport type IconTone169 = \'nav\' | \'create\' | \'edit\' | \'danger\' | \'view\' | \'layer\' | \'stair\' | \'object\' | \'power\'\nexport const iconSet169: Record<string, readonly [IconTone169, string]> = {\n  "chevron-right": ["nav", "<path d=\\"M9 5l7 7-7 7\\"/>"],\n  "chevron-left": ["nav", "<path d=\\"M15 5l-7 7 7 7\\"/>"],\n  "chevron-down": ["nav", "<path d=\\"M5 9l7 7 7-7\\"/>"],\n  "blueprint": ["nav", "<rect class=\\"at\\" x=\\"3.5\\" y=\\"3.5\\" width=\\"7\\" height=\\"7\\" rx=\\"1\\"/><rect class=\\"t\\" x=\\"13.5\\" y=\\"13.5\\" width=\\"7\\" height=\\"7\\" rx=\\"1\\"/><rect x=\\"3.5\\" y=\\"3.5\\" width=\\"7\\" height=\\"7\\" rx=\\"1\\"/><rect x=\\"13.5\\" y=\\"3.5\\" width=\\"7\\" height=\\"7\\" rx=\\"1\\"/><rect x=\\"3.5\\" y=\\"13.5\\" width=\\"7\\" height=\\"7\\" rx=\\"1\\"/><rect x=\\"13.5\\" y=\\"13.5\\" width=\\"7\\" height=\\"7\\" rx=\\"1\\"/>"],\n  "wall-detail": ["nav", "<rect class=\\"t\\" x=\\"4.5\\" y=\\"3.5\\" width=\\"15\\" height=\\"17\\" rx=\\"1\\"/><rect class=\\"at\\" x=\\"4.5\\" y=\\"9.3\\" width=\\"15\\" height=\\"5.4\\"/><rect x=\\"4.5\\" y=\\"3.5\\" width=\\"15\\" height=\\"17\\" rx=\\"1\\"/><path d=\\"M4.5 9.3h15M4.5 14.7h15\\"/>"],\n  "cube": ["nav", "<path class=\\"at\\" d=\\"M12 3l8 4.5-8 4.5-8-4.5z\\"/><path class=\\"t\\" d=\\"M4 7.5v9L12 21v-9z\\"/><path d=\\"M12 3l8 4.5v9L12 21l-8-4.5v-9z\\"/><path d=\\"M4 7.5 12 12l8-4.5M12 12v9\\"/>"],\n  "lightning": ["power", "<path class=\\"at\\" d=\\"M13.5 2.5 5.5 13.5h6l-1.5 8 8.5-11.5h-6z\\"/><path class=\\"a\\" d=\\"M13.5 2.5 5.5 13.5h6l-1.5 8 8.5-11.5h-6z\\"/>"],\n  "user": ["nav", "<circle class=\\"t\\" cx=\\"12\\" cy=\\"8\\" r=\\"4\\"/><circle cx=\\"12\\" cy=\\"8\\" r=\\"4\\"/><path d=\\"M4.5 20.5c0-4.2 3.4-7 7.5-7s7.5 2.8 7.5 7\\"/>"],\n  "logout": ["nav", "<path d=\\"M10.5 3.5h-6v17h6\\"/><path class=\\"a\\" d=\\"M14.5 8l4.5 4-4.5 4M9 12h10