}
assert(!fs.existsSync(path.join(source, '../public/strom-icons-v7.svg')), 'alte Sprite-Datei noch vorhanden')
assert(!/strom-icons-v7|<use\b/.test(app + ws + read('components/StromIcon.tsx')), 'Sprite-Verweis noch vorhanden')
